        LinearLayout config=card(body);label(config,"Configuration Preset");LinearLayout presets=e.row();String[] glyphs={"❄","💧","♥","✦","●"};for(int i=0;i<5;i++){final int n=i;Button b=l.pill(glyphs[i],()->{ParticleConfig next=ParticleConfig.preset(n,1);next.sprite=p.sprite;layer.particles=next;saved();particlePanel(layer);});b.setTextSize(20);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,e.dp(43),1);lp.setMargins(e.dp(2),e.dp(8),e.dp(2),e.dp(8));presets.addView(b,lp);}config.addView(presets);config.addView(e.text("Please set the details for various movements.",13,0xffa5a5a5));gap(config,15);
