        LinearLayout collision=card(body);for(int i=0;i<2;i++){final int k=i;label(collision,i==0?"Collision horizontally":"Collision vertically");Switch s=new Switch(e);s.setTextColor(white);s.setChecked(i==0?p.bounceX:p.bounceY);s.setText(s.isChecked()?"On":"Off");s.setOnCheckedChangeListener((b,on)->{if(k==0)p.bounceX=on;else p.bounceY=on;s.setText(on?"On":"Off");saved();});collision.addView(s,new LinearLayout.LayoutParams(-1,e.dp(48)));}
