        String[][] pages={{"Gallery","❄","♥","☀","☁","✿","★","●","✦","☾","◇","♡"},{"Gallery","✧","✳","✹","▲","◉","◈","❋","☽","♢","✺","✷"},{"●","○","■","□","▲","△","◆","◇","✦","★","♥","❄"}};
