        LinearLayout actions=e.row();Button cancel=plain("Cancel",d::dismiss),done=plain("Done",()->{String value=input.getText().toString().trim();if(value.isEmpty())return;Scene.Layer target=layer;if(target==null){e.add("text");target=e.selected;}target.content=value;target.bold=style[0];target.italic=style[1];target.underline=style[2];target.strike=style[3];target.font=font[0];d.dismiss();e.selected=target;saved();l.canvas();});done.setEnabled(!input.getText().toString().trim().isEmpty());input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){done.setEnabled(!s.toString().trim().isEmpty());}public void afterTextChanged(Editable x){}});actions.addView(cancel,new LinearLayout.LayoutParams(0,e.dp(48),1));actions.addView(done,new LinearLayout.LayoutParams(0,e.dp(48),1));b.addView(actions);bottom(d,b);input.requestFocus();if(d.getWindow()!=null)d.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_VISIBLE);
